# Минимальный HTTP/1.1-сервер на TCPServer для проверки клиента против
# недоверенных ответов: одно соединение — один запрос, ответ по таблице
# routes ("GET /path" => [code, body]). Все полученные запросы
# ("METHOD /path") копятся в #requests.
class FakeServer
  attr_reader :port, :requests

  def initialize(routes)
    @routes = routes
    @requests = []
    @socket = TCPServer.new("127.0.0.1", 0)
    @port = @socket.addr[1]
    @thread = Thread.new { serve }
  end

  def url
    "http://127.0.0.1:#{port}"
  end

  def stop
    @socket.close
    @thread.join(5)
  end

  # Тело листинга GET /blobs для пар [key, содержимое].
  def self.listing(*entries)
    JSON.generate(entries.map do |key, body|
      { "key" => key, "size" => body.bytesize, "sha256" => Digest::SHA256.hexdigest(body), "modified_at" => "2026-01-01T00:00:00Z" }
    end)
  end

  private

  def serve
    loop do
      client = @socket.accept
      line = client.gets
      break unless line

      client.gets("\r\n\r\n")
      method, path, = line.split(" ")
      @requests << "#{method} #{path}"
      code, body = @routes.fetch("#{method} #{path}", [404, "{\"error\":\"not_found\"}"])
      client.write("HTTP/1.1 #{code} X\r\nContent-Length: #{body.bytesize}\r\nConnection: close\r\n\r\n#{body}")
      client.close
    end
  rescue IOError, SystemCallError
    nil # сокет закрыт в stop
  end
end

